/// Pruning only saves work: a walk that declines to descend reaches exactly the
/// files a walk entering every directory includes.
///
/// [`gitignore_conformance`] holds the pruned walk against git, which prunes
/// too, so a walk pruning where it must not can still agree with git there.
/// This compares it with no pruning at all, across the ground truth and the
/// sets in [`SHALLOW`], [`UNBOUNDED`], [`LEADING`] and [`CLASSES`]. A
/// ground-truth case the filter refuses is skipped, since
/// [`gitignore_conformance`] counts it, and a set here that the filter refuses
/// fails the test.
#[test]
fn pruning_changes_no_answer() {
    for (rules, filter, tree) in walks() {
        assert_eq!(
            walk_tree_entering(&filter, tree, true).0,
            walk_tree_entering(&filter, tree, false).0,
            "pruning changes the files included under {rules:?}"
        );
    }
}

/// Reading the lines through the index changes no answer: each set
/// [`pruning_changes_no_answer`] walks includes the same files as alone in one
/// of the layouts [`indexed`] pads it into, each set taking the next layout in
/// turn.
#[test]
fn the_line_index_changes_no_answer() {
    for (index, (rules, filter, tree)) in walks().enumerate() {
        assert_eq!(
            walk_tree(&indexed(rules, index % LAYOUTS), tree),
            walk_tree(&filter, tree),
            "the index changes the files included under {rules:?}"
        );
    }
}

/// The ground-truth cases the filter accepts, over [`FILES`], and the sets in
/// [`SHALLOW`], [`UNBOUNDED`], [`LEADING`] and [`CLASSES`], over their trees.
/// A set the filter refuses panics.
fn walks() -> impl Iterator<
    Item = (
        &'static [&'static str],
        FilterInstance,
        &'static [&'static str],
    ),
> {
    let sets = SHALLOW
        .iter()
        .map(|(rules, _, _)| (*rules, DEEP))
        .chain(UNBOUNDED.iter().map(|rules| (*rules, DEEP)))
        .chain(LEADING.iter().map(|(rules, _)| (*rules, LEADING_TREE)))
        .chain(CLASSES.iter().map(|(rules, _)| (*rules, CLASS_TREE)))
        .map(|(rules, tree)| {
            let filter = build(rules).unwrap_or_else(|| panic!("{rules:?} is refused"));
            (rules, filter, tree)
        });
    CASES
        .iter()
        .filter_map(|case| Some((case.patterns, build(case.patterns)?, FILES)))
        .chain(sets)
}

/// A re-inclusion that cannot match below a directory does not send a walk
/// into it.
///
/// `!/*` compiles to `*`, which matches any one component and nothing below
/// it, so it keeps a walk out of the directories below the root ones. Each set
/// in [`SHALLOW`] includes the files and enters the directories listed with it.
/// Under `!/*` a root directory is itself included, and the files inside it stay
/// excluded unless another rule re-includes them.
#[test]
fn a_shallow_reinclusion_does_not_open_the_tree_below_it() {
    for (rules, files, entered) in SHALLOW {
        let filter = build(rules).unwrap_or_else(|| panic!("{rules:?} is refused"));
        let (included, walked) = walk_tree_entering(&filter, DEEP, true);
        assert_eq!(included, set(files), "files included under {rules:?}");
        assert_eq!(walked, set(entered), "directories entered under {rules:?}");
    }

    let filter = build(&["*", "!/*", "!a/b/**"]).expect("filter builds");
    for directory in ["a", "ab", "c"] {
        assert!(
            !filter.excludes(&path(directory), true),
            "!/* does not re-include the directory {directory}"
        );
    }
    for file in ["a/top.xml", "ab/f", "c/f"] {
        assert!(
            filter.excludes(&path(file), false),
            "!/* re-includes {file}, below the first level"
        );
    }
    assert!(filter.excludes_subtree(&path("c/d")));
    assert!(filter.excludes_subtree(&path("a/x")));
    assert!(!filter.excludes_subtree(&path("a/b")));
}

/// A re-inclusion sends a walk only into a directory whose components its own
/// leading components match, wildcard components included.
///
/// `Saved/` with `!*/Saved/Config/` is a `.loreignore` an Unreal project
/// holds: the rule names `Config` third, so nothing below `Game/Saved/Logs`
/// can match it. Each set in [`LEADING`] and [`CLASSES`] enters the
/// directories listed with it, and the walk verdict for a whole path agrees.
#[test]
fn a_reinclusion_reaches_only_below_its_leading_components() {
    use lore_revision::filter::Filter;
    use lore_revision::filter::FilterMode;

    let mut wrong = Vec::new();
    let sets = LEADING
        .iter()
        .map(|set| (set, LEADING_TREE))
        .chain(CLASSES.iter().map(|set| (set, CLASS_TREE)));
    for ((rules, entered), tree) in sets {
        let filter = build(rules).unwrap_or_else(|| panic!("{rules:?} is refused"));
        let (_, walked) = walk_tree_entering(&filter, tree, true);
        if walked != set(entered) {
            wrong.push(format!("{rules:?} enters {walked:?}"));
        }
    }

    let mut filter = Filter::default();
    filter.ignore = build(&["Saved/", "!*/Saved/Config/"]).expect("filter builds");
    for (directory, dropped) in [
        ("Game/Saved", false),
        ("Game/Saved/Config", false),
        ("Game/Saved/Logs", true),
        ("Game/Saved/Config2", true),
    ] {
        if filter.excludes_tree(&path(directory), true, FilterMode::Ignore) != dropped {
            wrong.push(format!("the walk verdict for {directory} is not {dropped}"));
        }
    }
    assert!(wrong.is_empty(), "{}", wrong.join("\n"));
}

/// Names at the first two levels of the randomized tree: text, case, a class and
/// a `*` as text, non-ASCII, and leading `!` and space.
const RANDOM_NAMES: &[&str] = &["a", "ab", "B", "x*", "[a]", "\u{c4}", " a", "!a", "?"];

/// Names at the third level of the randomized tree, fewer, since every walk
/// lists the children of a directory by scanning the whole tree.
const RANDOM_LEAVES: &[&str] = &["a", "B", "[a]"];

/// Components the randomized rules are built from: text, every wildcard, classes,
/// escapes, brace groups and globstars.
const RANDOM_COMPONENTS: &[&str] = &[
    "*", "?", "a*", "*a", "a?", "?b", "[a]", "[!a]*", "[A-C]*", "[^x]?", "\\*", "x\\*", "\\[a\\]",
    "\u{e4}*", "\u{c4}", "[\u{e4}]", "?*", "a", "ab", "b", "{a,b}", "{a,x*}", "\\!a", "!a", " a",
    "\\ a", "[a-b]", "[]a]", "a**", "**a", "\\a", "[!]a]", "**", "x*", "[[]a]", "\\?", "[?]",
    "[*]",
];

/// The exclusion each randomized filter opens with.
const RANDOM_EXCLUSIONS: &[&str] = &["**", "*", "/*", "a*/", "*/", "\u{c4}*/", "[ab]*/", "*/*/"];

/// Filters [`randomized_pruning_and_the_index_change_no_answer`] builds and checks.
const RANDOM_FILTERS: usize = 200;

/// A xorshift generator, so a seed reproduces the same filters everywhere.
struct Xorshift(u64);

impl Xorshift {
    fn pick<'a>(&mut self, items: &[&'a str]) -> &'a str {
        items[(self.next() % items.len() as u64) as usize]
    }

    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }

    /// A rule of one to three components, rooted, directory-only, with a `/**`
    /// tail, or none of those.
    fn rule(&mut self) -> String {
        let count = 1 + self.next() % 3;
        let mut rule = (0..count)
            .map(|_| self.pick(RANDOM_COMPONENTS))
            .collect::<Vec<_>>()
            .join("/");
        match self.next() % 4 {
            0 => rule.insert(0, '/'),
            1 => rule.push('/'),
            2 => rule.push_str("/**"),
            _ => {}
        }
        rule
    }
}

/// Pruning and reading the lines through the index change no answer, and no
/// subtree answer claims more than the walk finds, under randomized filters
/// whose rules mix every component kind the indexes compare or stop at, over a
/// tree whose names those components tell apart.
///
/// Each filter opens with an exclusion, re-includes one to three rules, and
/// half of them exclude and re-include once more. In every layout [`indexed`]
/// pads it into, it includes the same files. A directory
/// `excludes_subtree` drops holds nothing the walk includes, and one
/// `covers_subtree` takes whole holds nothing it excludes.
#[test]
fn randomized_pruning_and_the_index_change_no_answer() {
    use lore_revision::filter::Filter;
    use lore_revision::filter::FilterMode;

    let mut files = vec!["f".to_owned()];
    for a in RANDOM_NAMES {
        files.push(format!("{a}/f"));
        for b in RANDOM_NAMES {
            files.push(format!("{a}/{b}/f"));
            for c in RANDOM_LEAVES {
                files.push(format!("{a}/{b}/{c}/f"));
            }
        }
    }
    let tree: Vec<&str> = files.iter().map(String::as_str).collect();
    let dirs: BTreeSet<&str> = tree.iter().flat_map(|file| ancestors(file)).collect();

    let mut rng = Xorshift(0x9e37_79b9_7f4a_7c15);
    let mut wrong = Vec::new();
    for _ in 0..RANDOM_FILTERS {
        let mut lines = vec![rng.pick(RANDOM_EXCLUSIONS).to_owned()];
        for _ in 0..=rng.next() % 3 {
            lines.push(format!("!{}", rng.rule()));
        }
        if rng.next().is_multiple_of(2) {
            lines.push(rng.rule());
            lines.push(format!("!{}", rng.rule()));
        }
        let rules: Vec<&str> = lines.iter().map(String::as_str).collect();
        let Some(instance) = build(&rules) else {
            continue;
        };
        let included = walk_tree_entering(&instance, &tree, false).0;
        if walk_tree_entering(&instance, &tree, true).0 != included {
            wrong.push(format!(
                "pruning changes the files included under {rules:?}"
            ));
        }
        for layout in 0..LAYOUTS {
            if walk_tree(&indexed(&rules, layout), &tree) != included {
                wrong.push(format!(
                    "the index changes the files included under {rules:?}"
                ));
            }
        }

        let mut holds_included = BTreeSet::new();
        let mut holds_excluded = BTreeSet::new();
        for file in &tree {
            let holds = if included.contains(*file) {
                &mut holds_included
            } else {
                &mut holds_excluded
            };
            holds.extend(ancestors(file));
        }
        let mut filter = Filter::default();
        filter.view = instance.clone();
        for dir in &dirs {
            let directory = path(dir);
            if instance.excludes_subtree(&directory) && holds_included.contains(dir) {
                wrong.push(format!("{rules:?} drops {dir}, which holds included files"));
            }
            let depth = dir.split('/').count() as u32;
            let states = filter.exclusion_states(&directory);
            if filter.covers_subtree(states, &directory, depth, FilterMode::View)
                && holds_excluded.contains(dir)
            {
                wrong.push(format!(
                    "{rules:?} covers {dir}, which holds excluded files"
                ));
            }
        }
    }
    assert!(wrong.is_empty(), "{}", wrong.join("\n"));
}

/// The directories the pruned walk enters over the probe tree, the root
/// included, summed over every ground-truth case the filter accepts.
///
/// A sound prune changes no file a walk includes, only the directories it
/// enters, so across the whole table a prune lost or gained shows in this count
/// alone. [`a_shallow_reinclusion_does_not_open_the_tree_below_it`] and
/// [`excluded_subtree_with_no_reinclusion_is_not_descended`] check descent for
/// named rule sets.
#[test]
fn directories_entered_across_the_ground_truth_are_pinned() {
    let entered: usize = CASES
        .iter()
        .filter_map(|case| build(case.patterns))
        .map(|filter| walk_tree_entering(&filter, FILES, true).1.len())
        .sum();
    assert_eq!(
        entered, 21352,
        "the directories entered across the ground truth changed: a rise loses a \
         prune and a drop gains one, and either is reviewed before the pin moves"
    );
}

/// The ancestor memo changes no answer.
///
/// `Filter::excludes` folds a path's parent once per directory and caches it, so
/// a batch of paths sharing ancestors -- a targets file naming hundreds of
/// thousands of them -- pays for each directory once. `FilterInstance::excludes`
/// folds every path from the root with no cache. The two must agree on every
/// path of every case in the ground-truth table, or the cache is a bug.
#[test]
fn the_ancestor_memo_changes_no_answer() {
    use lore_revision::filter::Filter;
    use lore_revision::filter::FilterMode;

    let mut compared = 0usize;
    for case in CASES {
        let Some(instance) = build(case.patterns) else {
            continue;
        };
        let mut filter = Filter::default();
        filter.ignore = instance.clone();

        // Ask twice, so the second call is answered from a populated memo and
        // the first is not.
        for _ in 0..2 {
            for (probe, is_dir) in FILES
                .iter()
                .map(|f| (*f, false))
                .chain(DIRS.iter().map(|d| (*d, true)))
            {
                let path = path(probe);
                assert_eq!(
                    filter.excludes(&path, is_dir, FilterMode::Ignore),
                    instance.excludes(&path, is_dir),
                    "memo disagrees on {probe} for {:?}",
                    case.patterns
                );
                compared += 1;
            }
        }
    }
    assert!(
        compared > 100_000,
        "expected a broad comparison, got {compared}"
    );
}

/// Adding rules to a filter that has already answered empties the ancestor memo.
///
/// The slot fields are public and [`FilterInstance::add_exclusion`] takes
/// `&mut self`, so a caller can load a filter, query it, and then add to it. A
/// cached ancestor verdict from before the addition would answer with rules that
/// no longer describe the filter.
#[test]
fn adding_rules_after_a_query_invalidates_the_memo() {
    use lore_revision::filter::Filter;
    use lore_revision::filter::FilterMode;

    let mut filter = Filter::default();
    filter.ignore.add_exclusion("/a/b/c").expect("exclude");

    // Caches the verdict for `a/b`.
    assert!(filter.excludes(&path("a/b/c"), false, FilterMode::Ignore));
    assert!(!filter.excludes(&path("a/b/other"), false, FilterMode::Ignore));

    filter.ignore.add_exclusion("/a/b").expect("exclude");
    assert!(filter.excludes(&path("a/b/other"), false, FilterMode::Ignore));

    // And the other direction: a re-inclusion added later must take effect.
    filter.ignore.add_inclusion("/a/b/keep").expect("include");
    assert!(!filter.excludes(&path("a/b/keep"), false, FilterMode::Ignore));
}

/// A path has to clear both slots, and neither slot's rules leak into the other.
///
/// The ignore and view filters are folded together but decided separately: a view
/// re-inclusion cannot recover ignore-excluded content, and `FilterMode` selects
/// which slots are consulted at all.
#[test]
fn the_two_slots_are_independent_and_both_must_pass() {
    use lore_revision::filter::Filter;
    use lore_revision::filter::FilterMode;

    let mut filter = Filter::default();
    filter.ignore.add_exclusion("*.tmp").expect("exclude");
    filter.view.add_exclusion("**").expect("exclude");
    filter
        .view
        .add_inclusion("engine/content")
        .expect("include");

    // In view and not ignored.
    let kept = path("engine/content/asset.uasset");
    assert!(!filter.excludes(&kept, false, FilterMode::Full));
    assert!(!filter.excludes(&kept, false, FilterMode::Ignore));
    assert!(!filter.excludes(&kept, false, FilterMode::View));

    // In view, but the ignore slot excludes it. A view re-inclusion does not
    // recover it.
    let ignored = path("engine/content/scratch.tmp");
    assert!(filter.excludes(&ignored, false, FilterMode::Full));
    assert!(filter.excludes(&ignored, false, FilterMode::Ignore));
    assert!(!filter.excludes(&ignored, false, FilterMode::View));

    // Not ignored, but out of view.
    let unseen = path("game/content/asset.uasset");
    assert!(filter.excludes(&unseen, false, FilterMode::Full));
    assert!(!filter.excludes(&unseen, false, FilterMode::Ignore));
    assert!(filter.excludes(&unseen, false, FilterMode::View));

    // Descent is per slot: the view slot must be allowed to reach
    // `engine/content`, and neither slot has anything to find under `game`.
    let states = FilterStates::ROOT;
    let engine = path("engine");
    let (engine_states, _) = filter.child_exclusion_states(states, &engine, true, FilterMode::Full);
    assert!(filter.should_descend(engine_states, &engine, FilterMode::Full));

    let game = path("game");
    let (game_states, _) = filter.child_exclusion_states(states, &game, true, FilterMode::Full);
    assert!(!filter.should_descend(game_states, &game, FilterMode::Full));
}

/// `excludes_tree` keeps a directory a walk has to descend into.
///
/// This is the verdict a tree walk needs, and `excludes` is not it: with `**`
/// and `!included/**` the `included` directory matches only the blanket
/// exclusion, so `excludes` reports it excluded -- yet everything under it is in
/// view, and a sparse working tree cannot hold those files without the
/// directory. Pruning a walk on the node verdict strands the whole subtree.
#[test]
fn the_walk_verdict_keeps_a_directory_it_must_descend_into() {
    use lore_revision::filter::Filter;
    use lore_revision::filter::FilterMode;

    let mut filter = Filter::default();
    filter.view.add_exclusion("**").expect("exclude");
    filter.view.add_inclusion("included/**").expect("include");

    let included = path("included");
    assert!(filter.excludes(&included, true, FilterMode::View));
    assert!(!filter.excludes_tree(&included, true, FilterMode::View));
    assert!(!filter.excludes_tree(&path("included/a.txt"), false, FilterMode::View));

    // A sibling with nothing re-included below it is dropped whole.
    let excluded = path("excluded");
    assert!(filter.excludes(&excluded, true, FilterMode::View));
    assert!(filter.excludes_tree(&excluded, true, FilterMode::View));

    // A file answers the same to both, having no subtree to answer for.
    let dropped = path("excluded/x.txt");
    assert!(filter.excludes(&dropped, false, FilterMode::View));
    assert!(filter.excludes_tree(&dropped, false, FilterMode::View));
}

/// The two shapes a walk can take reach the same files.
///
/// A walk that holds its parent's [`FilterStates`] steps them with
/// `child_excludes_tree`; one handed a path with no walk behind it -- a change
/// list, a clone dependency, a path named on the command line -- asks
/// `excludes_tree` for the whole path. Both have to agree with [`walk_tree`] on
/// every case in the ground-truth table, or the same tree yields different
/// content depending on how it was reached.
#[test]
fn the_whole_path_walk_reaches_the_same_files_as_the_stepped_walk() {
    use lore_revision::filter::Filter;
    use lore_revision::filter::FilterMode;

    fn walk_whole_paths(filter: &Filter, tree: &[&str]) -> BTreeSet<String> {
        let mut included = BTreeSet::new();
        let mut stack = vec![String::new()];
        while let Some(dir) = stack.pop() {
            let (subdirs, files) = children(tree, &dir);
            for file in files {
                if !filter.excludes_tree(&path(&file), false, FilterMode::Ignore) {
                    included.insert(file);
                }
            }
            for subdir in subdirs {
                if !filter.excludes_tree(&path(&subdir), true, FilterMode::Ignore) {
                    stack.push(subdir);
                }
            }
        }
        included
    }

    fn walk_threaded(filter: &Filter, tree: &[&str]) -> BTreeSet<String> {
        let mut included = BTreeSet::new();
        let mut stack = vec![(String::new(), FilterStates::ROOT)];
        while let Some((dir, states)) = stack.pop() {
            let (subdirs, files) = children(tree, &dir);
            for file in files {
                let (_, excluded) =
                    filter.child_excludes_tree(states, &path(&file), false, FilterMode::Ignore);
                if !excluded {
                    included.insert(file);
                }
            }
            for subdir in subdirs {
                let (child, excluded) =
                    filter.child_excludes_tree(states, &path(&subdir), true, FilterMode::Ignore);
                if !excluded {
                    stack.push((subdir, child));
                }
            }
        }
        included
    }

    let mut compared = 0usize;
    for case in CASES {
        let Some(instance) = build(case.patterns) else {
            continue;
        };
        let mut filter = Filter::default();
        filter.ignore = instance.clone();
        let stepped = walk_tree(&instance, FILES);
        assert_eq!(
            walk_whole_paths(&filter, FILES),
            stepped,
            "the whole-path walk and the stepped walk disagree for {:?}",
            case.patterns
        );
        assert_eq!(
            walk_threaded(&filter, FILES),
            stepped,
            "the threaded walk and the stepped walk disagree for {:?}",
            case.patterns
        );
        compared += 1;
    }
    assert!(
        compared > 3_000,
        "expected a broad comparison, got {compared}"
    );
}

/// A walk that starts partway down the tree sees what a walk from the root sees
/// there.
///
/// Every walk entry point that is handed a subdirectory seeds itself with
/// `exclusion_states` (or `parent_exclusion_states` where the first step is the
/// path itself) rather than with [`FilterStates::ROOT`]. If that seed differed
/// from what the root walk reached, `lore status <dir>` would filter its subtree
/// differently from `lore status`.
#[test]
fn a_walk_seeded_partway_down_matches_one_from_the_root() {
    use lore_revision::filter::Filter;
    use lore_revision::filter::FilterMode;

    /// Every directory's states, as reached by stepping down from the root.
    fn stepped_states(
        filter: &Filter,
        tree: &[&str],
    ) -> std::collections::BTreeMap<String, FilterStates> {
        let mut reached = std::collections::BTreeMap::new();
        let mut stack = vec![(String::new(), FilterStates::ROOT)];
        while let Some((dir, states)) = stack.pop() {
            let (subdirs, _) = children(tree, &dir);
            for subdir in subdirs {
                let child = path(&subdir);
                let (child_states, excluded) =
                    filter.child_excludes_tree(states, &child, true, FilterMode::Ignore);
                reached.insert(subdir.clone(), child_states);
                if !excluded {
                    stack.push((subdir, child_states));
                }
            }
        }
        reached
    }

    let mut compared = 0usize;
    for case in CASES {
        let Some(instance) = build(case.patterns) else {
            continue;
        };
        let mut filter = Filter::default();
        filter.ignore = instance;

        for (dir, walked) in stepped_states(&filter, FILES) {
            let directory = path(&dir);
            // The seed a walk rooted at `dir` uses for its children.
            let seeded = filter.exclusion_states(&directory);
            // The seed a recursion that asks about `dir` itself uses, stepped
            // the one component it is about to ask about.
            let (from_parent, _) = filter.child_excludes_tree(
                filter.parent_exclusion_states(&directory),
                &directory,
                true,
                FilterMode::Ignore,
            );

            let (_, walked_excludes) = filter.child_excludes_tree(
                walked,
                &path(&format!("{dir}/probe")),
                false,
                FilterMode::Ignore,
            );
            for (label, seed) in [("exclusion_states", seeded), ("parent step", from_parent)] {
                let (_, seed_excludes) = filter.child_excludes_tree(
                    seed,
                    &path(&format!("{dir}/probe")),
                    false,
                    FilterMode::Ignore,
                );
                assert_eq!(
                    seed_excludes, walked_excludes,
                    "{label} at {dir} disagrees with the walk for {:?}",
                    case.patterns
                );
                assert_eq!(
                    filter.should_descend(seed, &directory, FilterMode::Ignore),
                    filter.should_descend(walked, &directory, FilterMode::Ignore),
                    "{label} descent at {dir} disagrees with the walk for {:?}",
                    case.patterns
                );
            }
            compared += 1;
        }
    }
    assert!(
        compared > 10_000,
        "expected a broad comparison, got {compared}"
    );
}

/// A threaded walk answers for both slots the way a whole-path query does.
///
/// The equivalence tests above run one slot, where a verdict cannot be reached
/// by the other. This puts rules in both and holds the threaded walk against
/// `excludes_tree`, which is the shape `FilterMode::Full` operations -- stage,
/// unstage, dirty -- ask in.
#[test]
fn a_threaded_walk_agrees_with_a_whole_path_query_across_both_slots() {
    use lore_revision::filter::Filter;
    use lore_revision::filter::FilterMode;

    let mut compared = 0usize;
    for ignore_case in CASES {
        let Some(ignore) = build(ignore_case.patterns) else {
            continue;
        };
        for view_case in CASES.iter().rev().take(8) {
            let Some(view) = build(view_case.patterns) else {
                continue;
            };
            let mut filter = Filter::default();
            filter.ignore = ignore.clone();
            filter.view = view;

            let mut stack = vec![(String::new(), FilterStates::ROOT)];
            while let Some((dir, states)) = stack.pop() {
                let (subdirs, files) = children(FILES, &dir);
                for file in files {
                    let file_path = path(&file);
                    let (_, threaded) =
                        filter.child_excludes_tree(states, &file_path, false, FilterMode::Full);
                    assert_eq!(
                        threaded,
                        filter.excludes_tree(&file_path, false, FilterMode::Full),
                        "file {file} disagrees for ignore {:?} view {:?}",
                        ignore_case.patterns,
                        view_case.patterns
                    );
                    compared += 1;
                }
                for subdir in subdirs {
                    let dir_path = path(&subdir);
                    let (child, threaded) =
                        filter.child_excludes_tree(states, &dir_path, true, FilterMode::Full);
                    assert_eq!(
                        threaded,
                        filter.excludes_tree(&dir_path, true, FilterMode::Full),
                        "directory {subdir} disagrees for ignore {:?} view {:?}",
                        ignore_case.patterns,
                        view_case.patterns
                    );
                    compared += 1;
                    if !threaded {
                        stack.push((subdir, child));
                    }
                }
            }
        }
    }
    assert!(
        compared > 10_000,
        "expected a broad comparison, got {compared}"
    );
}

/// A forced walk that steps no slot is answered without consulting the filter.
///
/// `--force` drops nothing, so it must report nothing excluded and emit no
/// event. It also reads no verdict -- every step below a forced one is forced
/// too -- so the state handed back is [`FilterStates::ROOT`] rather than one the
/// walk would have paid a line scan to produce.
#[test]
fn a_forced_step_excludes_nothing_and_carries_no_verdict() {
    use lore_revision::filter::Filter;
    use lore_revision::filter::FilterMode;

    let mut filter = Filter::default();
    filter
        .ignore
        .add_exclusion("intermediate")
        .expect("exclusion");
    filter.view.add_exclusion("binaries").expect("exclusion");

    for (name, is_directory) in [
        ("intermediate", true),
        ("binaries", true),
        ("keep.txt", false),
    ] {
        let subject = path(name);
        // The unforced control asks the non-emitting query: emitting needs a
        // task-local execution context this test has no other use for.
        let (unforced_states, unforced) = filter.child_excludes_tree(
            FilterStates::ROOT,
            &subject,
            is_directory,
            FilterMode::Full,
        );
        let (forced_states, forced) = filter.child_emit_unless_forced(
            true,
            FilterMode::empty(),
            FilterStates::ROOT,
            &subject,
            is_directory,
            FilterMode::Full,
        );
        assert!(
            !forced,
            "a forced step excludes nothing, {name} was dropped"
        );
        assert_eq!(
            forced_states,
            FilterStates::ROOT,
            "a forced step carries no verdict, {name} returned one"
        );
        let (tree_states, tree) = filter.child_excludes_tree_unless_forced(
            true,
            FilterStates::ROOT,
            &subject,
            is_directory,
            FilterMode::Full,
        );
        assert!(!tree, "a forced step excludes nothing, {name} was dropped");
        assert_eq!(tree_states, FilterStates::ROOT);
        // The rules do bite when the walk is not forced, or the assertions above
        // would hold for a filter that excludes nothing.
        if name != "keep.txt" {
            assert!(unforced, "{name} should be excluded when not forced");
            assert_ne!(unforced_states, FilterStates::ROOT);
        }
    }
}

/// A forced step that steps the view leaves out nothing, and hands back the view's step at a
/// directory with the ignore slot at its root state, and the root states at a file.
#[test]
fn a_forced_step_steps_only_the_slots_asked_for_at_a_directory() {
    use lore_revision::filter::Filter;
    use lore_revision::filter::FilterMode;

    let mut filter = Filter::default();
    filter
        .ignore
        .add_exclusion("intermediate")
        .expect("exclusion");
    filter.view.add_exclusion("binaries").expect("exclusion");

    for (name, is_directory) in [
        ("intermediate", true),
        ("binaries", true),
        ("binaries", false),
    ] {
        let subject = path(name);
        let (unforced_states, _) = filter.child_excludes_tree(
            FilterStates::ROOT,
            &subject,
            is_directory,
            FilterMode::Full,
        );
        let (forced_states, forced) = filter.child_emit_unless_forced(
            true,
            FilterMode::View,
            FilterStates::ROOT,
            &subject,
            is_directory,
            FilterMode::Full,
        );
        assert!(
            !forced,
            "a forced step excludes nothing, {name} was dropped"
        );
        let expected = if is_directory {
            FilterStates {
                ignore: FilterStates::ROOT.ignore,
                view: unforced_states.view,
            }
        } else {
            FilterStates::ROOT
        };
        assert_eq!(
            forced_states, expected,
            "a forced step of {name}, a directory {is_directory}, stepped other than the view"
        );
    }
}

/// A path the tree tracks is past the ignore slot, and only the view drops it.
///
/// The states a tracked step hands back are both slots' all the same, so an
/// untracked child of a tracked, ignored directory is still ignored while a
/// tracked one beside it is kept.
#[test]
fn a_tracked_step_answers_to_the_view_alone() {
    use lore_revision::filter::Filter;
    use lore_revision::filter::FilterMode;

    let mut filter = Filter::default();
    filter.ignore.add_exclusion("*.log").expect("exclusion");
    filter.ignore.add_exclusion("build/").expect("exclusion");
    filter.view.add_exclusion("binaries").expect("exclusion");

    // Path, is a directory, excluded untracked, excluded tracked.
    for (name, is_directory, untracked, tracked) in [
        ("debug.log", false, true, false),
        ("build", true, true, false),
        ("binaries", true, true, true),
        ("keep.txt", false, false, false),
    ] {
        let subject = path(name);
        for (is_tracked, expected) in [(false, untracked), (true, tracked)] {
            let (_, excluded) = filter.child_excludes_tree(
                FilterStates::ROOT,
                &subject,
                is_directory,
                FilterMode::TRACKED.at(is_tracked),
            );
            assert_eq!(
                excluded, expected,
                "{name} tracked {is_tracked} excluded {excluded}"
            );
        }
    }

    let (build_states, _) = filter.child_excludes_tree(
        FilterStates::ROOT,
        &path("build"),
        true,
        FilterMode::TRACKED.at(true),
    );
    let (_, untracked) = filter.child_excludes_tree(
        build_states,
        &path("build/new.txt"),
        false,
        FilterMode::TRACKED.at(false),
    );
    assert!(
        untracked,
        "an untracked file in an ignored directory stays ignored"
    );
    let (_, tracked) = filter.child_excludes_tree(
        build_states,
        &path("build/tracked.txt"),
        false,
        FilterMode::TRACKED.at(true),
    );
    assert!(!tracked, "a tracked file in an ignored directory is kept");
}

/// Folding a whole path and stepping down it one component at a time reach the
/// same verdict.
///
/// The two entry points answer the same question by different routes:
/// `exclusion_state` folds a path that arrives whole, `child_exclusion_state`
/// takes one step given the parent's verdict. They are the single-slot forms of a
/// whole-path query and a walk's step, so a divergence would make the tree
/// disagree with the paths named on the command line.
#[test]
fn folding_a_path_and_stepping_down_it_agree() {
    let mut compared = 0usize;
    for case in CASES {
        let Some(filter) = build(case.patterns) else {
            continue;
        };
        for (probe, is_dir) in FILES
            .iter()
            .map(|f| (*f, false))
            .chain(DIRS.iter().map(|d| (*d, true)))
        {
            let mut stepped = FilterState::ROOT;
            let mut walked = String::new();
            let mut components = probe.split('/').peekable();
            while let Some(component) = components.next() {
                if !walked.is_empty() {
                    walked.push('/');
                }
                walked.push_str(component);
                let last = components.peek().is_none();
                stepped = filter.child_exclusion_state(stepped, &path(&walked), !last || is_dir);
            }
            assert_eq!(
                stepped,
                filter.exclusion_state(&path(probe), is_dir),
                "fold and step disagree on {probe} for {:?}",
                case.patterns
            );
            compared += 1;
        }
    }
    assert!(
        compared > 50_000,
        "expected a broad comparison, got {compared}"
    );
}
